<div class="d-flex justify-content-between align-items-center mb-4"><h2>eBooks</h2></div><div class="card p-4 mb-4"><h5>Add New eBook</h5><?= validation_errors('<div class="alert alert-danger">','</div>') ?><?php if(!empty($error)): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="row g-3"><div class="col-md-6"><label class="form-label">Book Name</label><input class="form-control" name="book_name" required></div><div class="col-md-6"><label class="form-label">Author Name</label><input class="form-control" name="author_name" required></div><div class="col-md-6"><label class="form-label">Book Image</label><input class="form-control" type="file" name="book_image" accept="image/*" required></div><div class="col-md-6"><label class="form-label">Book PDF</label><input class="form-control" type="file" name="book_pdf" accept="application/pdf" required></div><div class="col-12"><button class="btn btn-primary">Add eBook</button></div></form></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0 admin-table"><thead><tr><th class="no-sort">Image</th><th>Book</th><th>Author</th><th>PDF</th><th class="no-sort">Action</th></tr></thead><tbody><?php foreach($ebooks as $e): ?><tr><td><?php if(!empty($e->book_image)): ?><img class="thumb" src="<?= base_url(ltrim($e->book_image,'/')) ?>"><?php endif; ?></td><td><?= html_escape($e->book_name) ?></td><td><?= html_escape($e->author_name) ?></td><td><a href="<?= base_url(ltrim($e->book_pdf,'/')) ?>" target="_blank" class="btn btn-sm btn-outline-secondary">Open PDF</a></td><td><a href="<?= site_url('admin/ebooks/delete/'.$e->id) ?>" class="btn btn-sm btn-outline-danger" onclick="return confirm('Delete this eBook?')">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></div>
